-- XMEDIA · proposta "Boat Event — Amsterdam · 14 Nov 2026" com preços estimados (catálogo de serviços),
-- link digital (30 dias) e orçamento na calculadora. Pode correr de novo: atualiza e cria um link novo. Devolve o link.
create or replace function pg_temp.publish_boat_proposal() returns text
language plpgsql as $fn$
declare
  v_owner uuid;
  v_token text := encode(extensions.gen_random_bytes(24), 'hex');
begin
  select id into v_owner from auth.users where lower(email) = 'contact@mediamarques.com';
  if v_owner is null then
    return 'Ainda sem admin: entre primeiro uma vez em /login com contact@mediamarques.com e corra este SQL de novo.';
  end if;

  insert into public.proposals (id, owner_id, title, client_name, value, currency, stage, data)
  values ('6f1c2a3e-8b4d-4f5a-9c7e-2d1b0a9e8f71', v_owner, 'Boat Event — Amsterdam · 14 Nov 2026', 'To be confirmed', 1510.4, 'EUR', 'diagnosis', $prop${"title": "Boat Event — Amsterdam · 14 Nov 2026", "client": {"name": "", "company": "To be confirmed", "email": ""}, "value": 1510.4, "currency": "EUR", "stage": "diagnosis", "sent_at": "", "valid_until": "2026-11-12", "notes": "Estimated proposal (scope not closed). Facts given by the client: 14 Nov 2026 · boat departs Amsterdam city centre 12:00 and returns to the same place · 2h30–3h · capture preparation & materials on board, guest arrival and atmosphere. Prices calculated with the XMEDIA services catalogue (Notion MM - Program Worksheet, 2026 rates) on the assumptions of slide 1.2: A Highlight €1,126 · B + Social €1,510.40 (recommended) · C Full €1,988.80 — excl. BTW. Volume discount B (4+ reels, 8%) applied to options B and C; hours discount on photography (4h, 8%) applied to C; no partner or recurring discount. Travel estimated at cost. Final price after the questions in slide 5.1.", "doc": {"meta": {"brand": "Media Marques Films ©", "line2": "Event Proposal", "year": "2026", "fao": "[ Boat Event Proposal ]"}, "theme": {"orange": "#FF4F2E", "dark": "#1C1C1C", "cream": "#ECE8E1", "paper": "#F6F5F2", "ink": "#111111", "gray": "#7A7A7A"}, "slides": [{"id": "s01", "type": "cover", "statement": "Preparation, guest arrival and the atmosphere of your boat event, documented with intention — from the first detail on board to the last guest stepping back on shore.", "mark": "MM®", "style": "gradient", "kicker": "Event Proposal · 14 November 2026", "title": "A moment on the water — Amsterdam"}, {"id": "s02", "type": "section", "number": "1", "title": "The brief", "text": "**What you shared with us** — an event on a boat in Amsterdam on **14 November 2026**. We document **the preparation, the guests' arrival and the atmosphere** — so the day lives on beyond the time on the water."}, {"id": "s03", "type": "list", "index": "1.1", "title": "What we know", "tone": "dark", "rows": [{"n": "1", "name": "Date", "text": "Saturday, 14 November 2026."}, {"n": "2", "name": "Route", "text": "The boat leaves from Amsterdam city centre at 12:00 and returns to the same place.\n[ Exact address of the pier — to be confirmed ]"}, {"n": "3", "name": "Duration", "text": "Between 2h30 and 3h on the water (expected return around 14:30–15:00)."}, {"n": "4", "name": "Coverage", "text": "Three moments requested by the client:\n[ Preparation & materials on board — Guests arriving — Atmosphere of the event ]"}]}, {"id": "s04", "type": "list", "index": "1.2", "title": "Our assumptions", "tone": "light", "rows": [{"n": "A", "name": "Access", "text": "Our crew can board **before the guests** to film the preparation and the materials. *Assumption — time to be confirmed.*"}, {"n": "B", "name": "Crew", "text": "One filmmaker on board is enough for the space; a second camera or a photographer is optional. *Assumption — depends on boat size and guest count.*"}, {"n": "C", "name": "Light", "text": "Mid-November daylight in Amsterdam is short and soft, and rain or wind are possible; we plan for low light, rain protection and the interior of the boat. *Assumption — final plan after the weather forecast.*"}, {"n": "D", "name": "Sound", "text": "No speeches or interviews need to be recorded with clean audio. *Assumption — if needed, we add audio equipment.*"}, {"n": "E", "name": "Consent", "text": "The client and the boat operator allow filming on board, and guests are informed that the event will be filmed. *Assumption — to be confirmed by the client.*"}]}, {"id": "s05", "type": "section", "number": "2", "title": "Creative approach", "text": "**Not a recording — a story in three acts.** — We follow the event as it naturally unfolds: **the quiet before, the welcome, and the life on the water.**"}, {"id": "s06", "type": "list", "index": "2.1", "title": "Three acts, one story", "tone": "dark", "rows": [{"n": "I", "name": "Before", "text": "Calm, detailed shots of the boat being prepared: materials, styling, textures, the city through the windows."}, {"n": "II", "name": "Arrival", "text": "The first guests on the quay and on board: welcomes, hands, smiles — the moment the boat fills with people."}, {"n": "III", "name": "Atmosphere", "text": "Departure from the centre and life on the water: conversations, details, canal views, the energy of the group — and the return to shore as the closing image."}, {"n": "—", "name": "Style", "text": "Discreet and observational: we stay unobtrusive and favour natural moments over posed shots."}]}, {"id": "s07", "type": "section", "number": "3", "title": "Shooting plan", "text": "A plan built around the **12:00 departure** — every block below is **anchored to the times you gave us**; arrival and set-up times are **suggestions to confirm**."}, {"id": "s08", "type": "cycle", "index": "3.1", "title": "The day, block by block", "steps": [{"days": "Before 12:00 · TBC", "name": "Set-up & preparation", "text": "Crew arrives before the guests. Details of the boat, materials and styling; establishing shots of the pier and the boat. [ Exact call time to be confirmed ]"}, {"days": "~11:30–12:00 · TBC", "name": "Guest arrival", "text": "Guests arriving on the quay and boarding: welcomes and first impressions. [ Depends on when guests are invited ]", "highlight": true}, {"days": "12:00", "name": "Departure", "text": "The boat leaves Amsterdam city centre: departure shots, first views of the canals."}, {"days": "12:00 – ~14:30", "name": "On the water", "text": "Atmosphere, people, interactions and details throughout the event; key moments if there are any (toast, speech, activity) — [ to be confirmed ]."}, {"days": "~14:30–15:00", "name": "Return", "text": "Arrival back at the same place and the last guests leaving — the closing image of the film."}], "note": "Total time on location: event duration (2h30–3h) plus set-up before departure. Final call sheet sent once the questions in section 5 are answered."}, {"id": "s09", "type": "list", "index": "3.2", "title": "Shot list (draft)", "tone": "dark", "rows": [{"n": "I", "name": "Before", "text": "Wide shots of the boat and the pier — details of materials, decoration and branding — the space before people arrive."}, {"n": "II", "name": "Arrival", "text": "Guests on the quay — boarding — welcome moments — first reactions inside the boat."}, {"n": "III", "name": "On board", "text": "Atmosphere and conversations — food, drinks and details (if part of the event) — canal and city views from the boat — group moments."}, {"n": "IV", "name": "Closing", "text": "Return to the pier — goodbyes — final wide shot of the boat."}]}, {"id": "s10", "type": "section", "number": "4", "title": "Deliverables & investment", "text": "**Choose what the day becomes.** — Three formats, **priced from the MediaMarques rate card**. Values are **estimates based on our assumptions** and are confirmed once section 5 is answered."}, {"id": "s11", "type": "list", "index": "4.1", "title": "Possible deliverables", "tone": "light", "rows": [{"n": "A", "name": "Highlight", "text": "One edited film that tells the day in three acts.\n[ Approx. 60–90 s — horizontal 16:9 — licensed music — colour grading — up to 2 rounds of adjustments ]\n*Estimated: €1,126 excl. BTW*"}, {"n": "B", "name": "+ Social", "text": "Option A plus three short vertical cuts for social media.\n[ 3 × vertical 9:16 cut-downs — versions for Instagram / LinkedIn — volume condition applied ]\n*Estimated: €1,510.40 excl. BTW — recommended*"}, {"n": "C", "name": "Full", "text": "Option B plus a photographer on board.\n[ Event photographer for 4h — approx. 100 edited photos (~25 per hour) ]\n*Estimated: €1,988.80 excl. BTW*"}, {"n": "—", "name": "Note", "text": "All options are proposals, not a confirmed scope. Delivery time and final quantities are defined together before confirmation."}]}, {"id": "s11b", "type": "list", "index": "4.2", "title": "Investment — option B", "tone": "dark", "rows": [{"n": "1", "name": "Pre-production", "text": "Shooting plan, shot list and call sheet (1h).\n€150.00"}, {"n": "2", "name": "Capture PRO", "text": "4h on location: set-up before 12:00 and up to 3h on board — 1 filmmaker, cinematic light and movement.\n4 × €114.00 = €456.00"}, {"n": "3", "name": "Highlight film", "text": "Complete PRO edit of the 60–90 s film — narrative edit, colour grading and sound design included.\n2 × €185.00 − 8% volume = €340.40"}, {"n": "4", "name": "Social cuts", "text": "3 vertical 9:16 cut-downs from the same footage.\n3 × €150.00 − 8% volume = €414.00"}, {"n": "5", "name": "Travel", "text": "Charged at cost — €0.40/km + parking (estimate).\n€150.00"}, {"n": "Σ", "name": "Total", "text": "*€1,510.40 excl. BTW* — BTW 21% €317.18 — **€1,827.58 incl. BTW**"}]}, {"id": "s11c", "type": "list", "index": "4.3", "title": "Conditions", "tone": "light", "rows": [{"n": "A", "name": "Options", "text": "A Highlight €1,126.00 — B + Social €1,510.40 — C Full €1,988.80.\n[ All excl. BTW 21% · incl. BTW: €1,362.46 — €1,827.58 — €2,406.45 ]"}, {"n": "B", "name": "Basis", "text": "MediaMarques 2026 rate card. Combined discounts never exceed 35%; no partner or recurring discount applied to a one-off event."}, {"n": "C", "name": "Extra time", "text": "Additional time on location beyond 4h: €114 per hour (capture PRO) — €130 per hour (photography)."}, {"n": "D", "name": "Payment", "text": "50% deposit to confirm 14 November; balance within 5 days after final delivery."}, {"n": "E", "name": "Validity", "text": "Estimate valid until 12 November 2026. *Final price confirmed after the answers in section 5 — a larger boat, a second camera or clean audio change the scope.*"}]}, {"id": "s12", "type": "list", "index": "5.1", "title": "Questions to confirm the quote", "tone": "light", "rows": [{"n": "1", "name": "Event", "text": "What is the event (brand, private, corporate) and who is the host? Which company and contact should the proposal and invoice go to?"}, {"n": "2", "name": "Boat", "text": "Which boat and exact departure point? How many guests, and how much space is there for the crew?"}, {"n": "3", "name": "Access", "text": "At what time can we board to film the preparation, and when will the guests arrive?"}, {"n": "4", "name": "Moments", "text": "Is there anything that must be captured: speeches, toast, performance, products, branding or specific people?"}, {"n": "5", "name": "Use", "text": "Where will the content be used (social media, website, internal, ads) and in which formats?"}, {"n": "6", "name": "Delivery", "text": "When do you need the first and the final deliverables?"}, {"n": "7", "name": "Extras", "text": "Do you also need photography, interviews or clean audio?"}, {"n": "8", "name": "Consent", "text": "Are guests informed about filming, and are there people who should not appear?"}, {"n": "9", "name": "Budget", "text": "Does the estimate fit your budget, or should we adapt the scope (e.g. option A, or adding photography)?"}]}, {"id": "s13", "type": "closing", "text": "**Next step** — choose an option and answer section 5; we return the **final scope, call sheet and invoice for the 50% deposit** for 14 November.\n\ncontact@mediamarques.com", "mark": "MM®"}]}}$prop$::jsonb)
  on conflict (id) do update set title = excluded.title, value = excluded.value, data = excluded.data, stage = excluded.stage, updated_at = now();

  update public.proposal_shares set revoked = true where proposal_id = '6f1c2a3e-8b4d-4f5a-9c7e-2d1b0a9e8f71' and not revoked;
