  insert into public.service_quotes (id, owner_id, client_name, total, data)
  values ('b0a7e0e1-14b1-4c26-9e11-202611140001', v_owner, 'Boat Event — To be confirmed', 1827.58, $q${"title": "Boat Event — 14 Nov 2026 (option B)", "status": "draft", "subtotal": 1510.4, "total": 1827.58, "proposal_id": "6f1c2a3e-8b4d-4f5a-9c7e-2d1b0a9e8f71", "input": {"client": {"name": "", "company": "To be confirmed", "email": "", "country": "NL", "customer_id": null}, "partner": false, "recurring_months": 0, "rush": false, "extra_discount_pct": 0, "note": "Boat event, Amsterdam centre 12:00, 2h30–3h on board.", "lines": [{"service_id": "strategy-on-demand", "qty": 1}, {"service_id": "cap-pro-on-demand", "qty": 4}, {"service_id": "edit-pro", "qty": 2}, {"service_id": "travel-on-demand", "qty": 1}, {"service_id": "pkg-extra-pro", "qty": 3}]}, "id": "b0a7e0e1-14b1-4c26-9e11-202611140001"}$q$::jsonb)
